// Ascending: act BEFORE recursing -- the work happens on the way DOWN.
void printAsc(int n, vector<int>& out) {
    if (n == 0) return;
    printAsc(n - 1, out);
    out.push_back(n);          // AFTER the call: prints on the unwind, so 1..N
}

// Descending: act BEFORE recursing -- prints on the way down, so N..1.
void printDesc(int n, vector<int>& out) {
    if (n == 0) return;
    out.push_back(n);          // BEFORE the call
    printDesc(n - 1, out);
}

