def print_asc(n: int) -> list:
    out = []
    def rec(k):
        if k == 0:
            return
        rec(k - 1)
        out.append(k)      # AFTER the call: emits on the unwind, so 1..N
    rec(n)
    return out


def print_desc(n: int) -> list:
    out = []
    def rec(k):
        if k == 0:
            return
        out.append(k)      # BEFORE the call: emits on the way down, so N..1
        rec(k - 1)
    rec(n)
    return out

