def reverse_rec(a: list, l: int = 0, r: int = None) -> list:
    if r is None:
        r = len(a) - 1
    if l >= r:
        return a               # base: pointers met or crossed
    a[l], a[r] = a[r], a[l]    # swap BEFORE recursing
    return reverse_rec(a, l + 1, r - 1)

