    return is_pal_rec(s, l + 1, r - 1)


def is_pal_rec_ci(s: str, l: int = 0, r: int = None) -> bool:
    """Case-insensitive: fold both sides before comparing."""
    if r is None:
        r = len(s) - 1
    if l >= r:
        return True
    if s[l].lower() != s[r].lower():
        return False
    return is_pal_rec_ci(s, l + 1, r - 1)

