long long powFast(long long b, long long e) {
    if (e == 0) return 1;
    long long half = powFast(b, e / 2);      // ONE call, reused twice
    long long sq = half * half;
    return (e % 2) ? sq * b : sq;            // odd exponent needs one extra b
}

// Linear version for contrast: e multiplications instead of log e.
long long powSlow(long long b, long long e) {
    if (e == 0) return 1;
    return b * powSlow(b, e - 1);
}
// MULTIPLICATION COUNTS for e = 1024: powFast ~ 10, powSlow = 1024.

solutionCode.py:
def pow_fast(b: int, e: int) -> int:
    if e == 0:
        return 1
    half = pow_fast(b, e // 2)     # ONE call, reused twice
    sq = half * half
    return sq * b if e % 2 else sq  # odd exponent needs one extra b


def pow_slow(b: int, e: int) -> int:
    """Linear version for contrast: e multiplications instead of log e."""
    if e == 0:
        return 1
    return b * pow_slow(b, e - 1)
# For e = 1024: pow_fast does ~10 multiplications, pow_slow does 1024.

