// CONVENTION: the number 0 has ONE digit, which is a zero -- so countZeros(0) == 1.
// The recursive helper uses n == 0 as "no digits left", so the two meanings must
// be separated by a wrapper. Mixing them is the whole trap in this problem.
int countZerosHelper(int n) {
    if (n == 0) return 0;                                  // no digits remain
    return (n % 10 == 0 ? 1 : 0) + countZerosHelper(n / 10);
}

int countZeros(int n) {
    n = abs(n);
    if (n == 0) return 1;              // the digit zero, not "nothing left"
    return countZerosHelper(n);
}

