def count_zeros_helper(n: int) -> int:
    """n == 0 here means NO DIGITS LEFT, not the digit zero."""
    if n == 0:
        return 0
    return (1 if n % 10 == 0 else 0) + count_zeros_helper(n // 10)


def count_zeros(n: int) -> int:
    """CONVENTION: the number 0 has one digit, which is a zero, so this returns 1.

    The helper's base case means "no digits remain", a different thing. Keeping
    the two meanings in separate functions is the point of this problem."""
    n = abs(n)
    if n == 0:
        return 1
    return count_zeros_helper(n)

