bool isSortedRec(const vector<int>& a, int i = 0) {
    if (i >= (int)a.size() - 1) return true;     // base: 0 or 1 element remains
    // && short-circuits: on a violation the recursive call never happens
    return a[i] <= a[i + 1] && isSortedRec(a, i + 1);
}

